/* Rack theme effects */
@keyframes rk-led {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

@keyframes rk-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(0.95); }
}

