import * as React from "react"
import { cn } from "@/lib/utils"

interface CrtLedProps extends React.HTMLAttributes<HTMLSpanElement> {
  color?: string
}

export function CrtLed({ 
  className, 
  color = "var(--accent)",
  ...props 
}: CrtLedProps) {
  return (
    <span 
      className={cn("inline-block w-[9px] h-[9px] rounded-full mr-1 align-middle", className)}
      style={{
        background: color,
        boxShadow: `0 0 8px ${color}`,
        animation: "crt-led 1.2s ease-in-out infinite",
      }}
      {...props}
    />
  )
}

/* CRT theme effects */
@keyframes crt-blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

@keyframes crt-led {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

import * as React from "react"
import { cn } from "@/lib/utils"

interface GlitchTextProps extends React.HTMLAttributes<HTMLDivElement> {
  text?: string
}

export function GlitchText({ 
  className, 
  text = "404",
  ...props 
}: GlitchTextProps) {
  return (
    <div 
      className={cn(
        "relative font-display text-[110px] font-black leading-none",
        className
      )}
      style={{
        color: "var(--accent)",
        textShadow: "3px 0 var(--accent-2), -3px 0 #ffff00",
        animation: "gp-glitch 3s ease-in-out infinite",
      }}
      {...props}
    >
      <span className="relative z-10">{text}</span>
      <span 
        className="absolute top-0 left-0 pointer-events-none"
        style={{
          color: "var(--accent-2)",
          clipPath: "inset(20% 0 60% 0)",
          animation: "gp-glitch-offset 2s ease-in-out infinite",
        }}
        aria-hidden="true"
      >
        {text}
      </span>
      <span 
        className="absolute top-0 left-0 pointer-events-none"
        style={{
          color: "#ffff00",
          clipPath: "inset(60% 0 10% 0)",
          animation: "gp-glitch-offset 3s ease-in-out infinite reverse",
        }}
        aria-hidden="true"
      >
        {text}
      </span>
    </div>
  )
}

